INSERT INTO `jobs` (`job_id`, `employer_id`, `industry_id`, `department_id`, `position_id`, `title`, `description`, `slug`, `salary_from`, `salary_to`, `salary_currency`, `gender`, `languages`, `combined_filters`, `last_date`, `hide_job_after_last_date`, `is_static_allowed`, `status`, `created_at`, `updated_at`) VALUES
(1, 1, 2, 2, 1, 'Build Magento eCommerce Site for Physical Goods', '<p style=\"background-color:rgb(255,255,255);color:rgb(14,23,36);font-family:Roboto, \'Helvetica Neue\', Helvetica, Arial, sans-serif;font-size:15px;font-style:normal;font-weight:400;letter-spacing:normal;line-height:1.4;margin-bottom:24px;text-indent:0px;text-transform:none;white-space:normal;word-spacing:0px;\">I\'m looking for a skilled web developer with extensive experience in Magento to create a robust eCommerce website for selling physical goods.</p><p style=\"background-color:rgb(255,255,255);color:rgb(14,23,36);font-family:Roboto, \'Helvetica Neue\', Helvetica, Arial, sans-serif;font-size:15px;font-style:normal;font-weight:400;letter-spacing:normal;line-height:1.4;margin-bottom:24px;text-indent:0px;text-transform:none;white-space:normal;word-spacing:0px;\"> </p><p style=\"background-color:rgb(255,255,255);color:rgb(14,23,36);font-family:Roboto, \'Helvetica Neue\', Helvetica, Arial, sans-serif;font-size:15px;font-style:normal;font-weight:400;letter-spacing:normal;line-height:1.4;margin-bottom:24px;text-indent:0px;text-transform:none;white-space:normal;word-spacing:0px;\">Key Requirements:</p><p style=\"background-color:rgb(255,255,255);color:rgb(14,23,36);font-family:Roboto, \'Helvetica Neue\', Helvetica, Arial, sans-serif;font-size:15px;font-style:normal;font-weight:400;letter-spacing:normal;line-height:1.4;margin-bottom:24px;text-indent:0px;text-transform:none;white-space:normal;word-spacing:0px;\">- Proficient in Magento: The website will be built on the Magento platform, so expertise in this area is crucial.</p><p style=\"background-color:rgb(255,255,255);color:rgb(14,23,36);font-family:Roboto, \'Helvetica Neue\', Helvetica, Arial, sans-serif;font-size:15px;font-style:normal;font-weight:400;letter-spacing:normal;line-height:1.4;margin-bottom:24px;text-indent:0px;text-transform:none;white-space:normal;word-spacing:0px;\">- eCommerce Development: Previous experience in developing eCommerce sites is a must.</p><p style=\"background-color:rgb(255,255,255);color:rgb(14,23,36);font-family:Roboto, \'Helvetica Neue\', Helvetica, Arial, sans-serif;font-size:15px;font-style:normal;font-weight:400;letter-spacing:normal;line-height:1.4;margin-bottom:24px;text-indent:0px;text-transform:none;white-space:normal;word-spacing:0px;\">- Physical Goods Cataloguing: Understanding of how to structure and present a physical goods inventory online.</p><p style=\"background-color:rgb(255,255,255);color:rgb(14,23,36);font-family:Roboto, \'Helvetica Neue\', Helvetica, Arial, sans-serif;font-size:15px;font-style:normal;font-weight:400;letter-spacing:normal;line-height:1.4;margin-bottom:24px;text-indent:0px;text-transform:none;white-space:normal;word-spacing:0px;\"> </p><p style=\"background-color:rgb(255,255,255);color:rgb(14,23,36);font-family:Roboto, \'Helvetica Neue\', Helvetica, Arial, sans-serif;font-size:15px;font-style:normal;font-weight:400;letter-spacing:normal;line-height:1.4;margin-bottom:24px;text-indent:0px;text-transform:none;white-space:normal;word-spacing:0px;\">Payment Integration Skills:</p><p style=\"background-color:rgb(255,255,255);color:rgb(14,23,36);font-family:Roboto, \'Helvetica Neue\', Helvetica, Arial, sans-serif;font-size:15px;font-style:normal;font-weight:400;letter-spacing:normal;line-height:1.4;margin-bottom:24px;text-indent:0px;text-transform:none;white-space:normal;word-spacing:0px;\">- Credit/Debit Card: The site must securely process credit and debit card transactions.</p><p style=\"background-color:rgb(255,255,255);color:rgb(14,23,36);font-family:Roboto, \'Helvetica Neue\', Helvetica, Arial, sans-serif;font-size:15px;font-style:normal;font-weight:400;letter-spacing:normal;line-height:1.4;margin-bottom:24px;text-indent:0px;text-transform:none;white-space:normal;word-spacing:0px;\">- PayPal: I also want to include PayPal as a payment option.</p><p style=\"background-color:rgb(255,255,255);color:rgb(14,23,36);font-family:Roboto, \'Helvetica Neue\', Helvetica, Arial, sans-serif;font-size:15px;font-style:normal;font-weight:400;letter-spacing:normal;line-height:1.4;margin-bottom:24px;text-indent:0px;text-transform:none;white-space:normal;word-spacing:0px;\"> </p><p style=\"background-color:rgb(255,255,255);color:rgb(14,23,36);font-family:Roboto, \'Helvetica Neue\', Helvetica, Arial, sans-serif;font-size:15px;font-style:normal;font-weight:400;letter-spacing:normal;line-height:1.4;margin-bottom:24px;text-indent:0px;text-transform:none;white-space:normal;word-spacing:0px;\">The ideal candidate will have a portfolio of successful eCommerce websites, particularly those built on Magento, and can demonstrate their ability to create a user-friendly, secure site that effectively showcases and sells physical products.</p>', 'build-magento-ecommerce-site-for-physical-goods', NULL, NULL, NULL, NULL, NULL, '1-2,1-3', '2024-12-30 00:00:00', 1, 0, 1, '2024-12-19 01:17:46', '2024-12-28 12:46:01'),
(2, 1, 2, 19, 25, 'Test 2', '<p><span style=\"background-color:rgb(255,255,255);color:rgb(51,51,51);float:none;font-family:\'Plus Jakarta Sans\', \'Helvetica Neue\', Helvetica, Arial, sans-serif;font-size:14px;font-style:normal;letter-spacing:normal;text-indent:0px;text-transform:none;white-space:normal;word-spacing:0px;\"><strong>AçıklamaAçıklamaAçıklamaAçıklamaAçıklamaAçıklamaAçıklamaAçıklamaAçıklamaAçıklamaAçıklamaAçıklamaAçıklamaAçıklamaAçıklamaAçıklama</strong></span></p>', 'test', '1500', '2500', 'usd', 'male', 'da_b1,et_b1,nl_c2,el_c1', '', '2026-09-30 00:00:00', 1, 1, 1, '2024-12-25 17:32:57', '2024-12-28 12:46:00');

