(97, 0, 'Email Templates', 'candidate_reset_password', '<!DOCTYPE html>\r\n<html lang=\"en\" xmlns=\"http://www.w3.org/1999/xhtml\" xmlns:o=\"urn:schemas-microsoft-com:office:office\">\r\n    <head>\r\n        <meta charset=\"utf-8\">\r\n        <meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\r\n        <meta name=\"x-apple-disable-message-reformatting\">\r\n        <title></title>\r\n        <!--[if mso]>\r\n        <style>\r\n            table {border-collapse:collapse;border-spacing:0;border:none;margin:0;}\r\n            div, td {padding:0;}\r\n            div {margin:0 !important;}\r\n        </style>\r\n        <noscript>\r\n            <xml><o:OfficeDocumentSettings><o:PixelsPerInch>96</o:PixelsPerInch></o:OfficeDocumentSettings></xml>\r\n        </noscript>\r\n        <![endif]-->\r\n        <style>\r\n            table, td, div, h1, p {font-family: Arial, sans-serif;}\r\n            @media screen and (max-width: 530px) {\r\n                .unsub {display: block; padding: 8px; margin-top: 14px; border-radius: 6px; background-color: #555555;\r\n                text-decoration: none !important; font-weight: bold;}\r\n                .col-lge {max-width: 100% !important;}\r\n            }\r\n            @media screen and (min-width: 531px) {\r\n                .col-sml {max-width: 27% !important;}\r\n                .col-lge {max-width: 73% !important;}\r\n            }\r\n        </style>\r\n    </head>\r\n    <body style=\"margin:0;padding:0;word-spacing:normal;background-color:#dadada;\">\r\n        <div role=\"article\" aria-roledescription=\"email\" lang=\"en\" style=\"text-size-adjust:100%;-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%;background-color:#dadada;\">\r\n            <table role=\"presentation\" style=\"width:100%;border:none;border-spacing:0;\">\r\n                <tr>\r\n                    <td align=\"center\" style=\"padding:0;\">\r\n                        <!--[if mso]>\r\n                        <table role=\"presentation\" align=\"center\" style=\"width:600px;\">\r\n                            <tr>\r\n                                <td>\r\n                                    <![endif]-->\r\n                                    <table role=\"presentation\" style=\"width:94%;max-width:600px;border:none;border-spacing:0;text-align:left;font-family:Arial,sans-serif;font-size:16px;line-height:22px;color:#363636;\">\r\n                                        <tr>\r\n                                            <td style=\"padding:40px 30px 30px 30px;text-align:center;font-size:24px;font-weight:bold;\">\r\n                                                <a href=\"((site_link))\" style=\"text-decoration:none;\"><img src=\"((site_logo))\" height=\"200\" alt=\"Logo\" style=\"width:80%;height:165px;height:auto;border:none;text-decoration:none;color:#ffffff;\"></a>\r\n                                            </td>\r\n                                        </tr>\r\n                                        <tr>\r\n                                            <td style=\"padding:30px;background-color:#ffffff;\">\r\n                                                <h1 style=\"margin-top:0;margin-bottom:16px;font-size:26px;line-height:32px;font-weight:bold;letter-spacing:-0.02em;\">\r\n                                                    Hello ((first_name)) ((last_name)),\r\n                                                </h1>\r\n                                                <p style=\"margin:0;\">\r\n                                                    As you have requested, below is the link to reset your password. If this is not requested by you, please report this activity.<br /><br />\r\n                                                    <a target=\"_blank\" href=\"((link))\">Reset Password</a><br /><br />\r\n                                                	Thanks & Regards,<br />\r\n                                                	Admin\r\n                                                </p>\r\n                                            </td>\r\n                                        </tr>\r\n                                        <tr>\r\n                                            <td style=\"padding:30px;text-align:center;font-size:12px;background-color:#404040;color:#cccccc;\">\r\n                                                <p style=\"margin:0;font-size:14px;line-height:20px;\">\r\n                                                    &copy; All Rights Reserved.\r\n                                                </p>\r\n                                            </td>\r\n                                        </tr>\r\n                                    </table>\r\n                                    <!--[if mso]>\r\n                                </td>\r\n                            </tr>\r\n                        </table>\r\n                        <![endif]-->\r\n                    </td>\r\n                </tr>\r\n            </table>\r\n        </div>\r\n    </body>\r\n</html>', NULL, NULL),
