       	Thanks & Regards,<br />\r\n                                                	Admin\r\n                                                </p>\r\n                                            </td>\r\n                                        </tr>\r\n                                        <tr>\r\n                                            <td style=\"padding:30px;text-align:center;font-size:12px;background-color:#404040;color:#cccccc;\">\r\n                                                <p style=\"margin:0;font-size:14px;line-height:20px;\">\r\n                                                    &copy; All Rights Reserved.\r\n                                                </p>\r\n                                            </td>\r\n                                        </tr>\r\n                                    </table>\r\n                                    <!--[if mso]>\r\n                                </td>\r\n                            </tr>\r\n                        </table>\r\n                        <![endif]-->\r\n                    </td>\r\n                </tr>\r\n            </table>\r\n        </div>\r\n    </body>\r\n</html>', NULL, NULL),
